/* Influencer Dashboard — Phase 2 vertical slice.
 *
 * Renderers ONLY: this file consumes window.DATA (the single source of truth
 * generated by scripts/generate-data.py) and renders it into the static
 * markup in index.html. It performs NO derived-rollup computation — all
 * rollups come precomputed from data.js > derived.
 */
(function () {
  "use strict";

  var DATA = window.DATA;

  if (!DATA || !DATA.derived) {
    console.error("Influencer Dashboard: window.DATA not found. Did data.js load before app.js?");
    return;
  }

  var derived = DATA.derived;

  /* ---------- tiny DOM helpers (textContent only — no HTML injection) ---------- */

  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined && text !== null) node.textContent = text;
    return node;
  }

  function usd(value) {
    return "$" + Number(value).toLocaleString("en-US", { maximumFractionDigits: 0 });
  }

  function pct(value) {
    return Number(value).toFixed(1) + "%";
  }

  function deltaBadge(percent, suffix) {
    var positive = Number(percent) >= 0;
    var arrow = positive ? "\u25B2 " : "\u25BC "; // ▲ / ▼
    var cls = positive
      ? "text-green-600 dark:text-green-400"
      : "text-red-500 dark:text-red-400";
    var badge = el("span", cls + " inline-flex items-center gap-0.5 font-medium");
    badge.appendChild(document.createTextNode(arrow + Math.abs(Number(percent)) + (suffix || "%")));
    return badge;
  }

  /* ---------- 1. KPI cards ---------- */

  var platformName = {};
  DATA.platforms.forEach(function (p) { platformName[p.id] = p.name; });
  var productName = {};
  DATA.products.forEach(function (p) { productName[p.id] = p.name; });

  function kpiCard(label, value, sub, deltaNode, accent) {
    var card = el("article", "bg-white dark:bg-slate-800 rounded-xl shadow-sm p-4 lg:p-6");
    var head = el("div", "flex items-center justify-between mb-3");
    head.appendChild(el("p", "text-sm font-semibold uppercase tracking-wide text-gray-500 dark:text-slate-400", label));
    var icon = el("span", "flex items-center justify-center w-10 h-10 rounded-lg text-lg",
      accent && accent.icon ? accent.icon : "\u2022");
    icon.className += " " + (accent ? accent.bg : "bg-gray-100 dark:bg-slate-700");
    icon.setAttribute("aria-hidden", "true");
    head.appendChild(icon);
    card.appendChild(head);

    var valueEl = el("p", "text-3xl font-bold tracking-tight", value);
    card.appendChild(valueEl);

    var foot = el("div", "mt-2 flex items-center gap-2 text-sm");
    if (deltaNode) foot.appendChild(deltaNode);
    if (sub) foot.appendChild(el("span", "text-gray-600 dark:text-slate-400", sub));
    card.appendChild(foot);
    return card;
  }

  var grid = document.getElementById("kpi-grid");
  if (grid) {
    var totalCommission = kpiCard(
      "Total Commissions",
      usd(derived.totalCommission),
      "this period",
      deltaBadge(derived.totalCommissionDeltaPct, "%"),
      { bg: "bg-emerald-100 dark:bg-emerald-500/20", icon: "\uD83D\uDCB0" }
    );

    var totalRevenue = kpiCard(
      "Total Revenue",
      usd(derived.totalRevenue),
      "attributable sales",
      deltaBadge(derived.totalRevenueDeltaPct, "%"),
      { bg: "bg-sky-100 dark:bg-sky-500/20", icon: "\uD83D\uDCC8" }
    );

    var topPlatform = kpiCard(
      "Top Platform",
      platformName[derived.topPlatform] || derived.topPlatform,
      pct(derived.platformRevenueShare[derived.topPlatform]) + " of revenue",
      null,
      { bg: "bg-violet-100 dark:bg-violet-500/20", icon: "\uD83C\uDF9F\uFE0F" }
    );

    var engagement = kpiCard(
      "Avg Engagement Rate",
      pct(derived.avgEngagementRate),
      "across platforms",
      deltaBadge(derived.avgEngagementDeltaPct, "pt"),
      { bg: "bg-teal-100 dark:bg-teal-500/20", icon: "\uD83D\uDC65" }
    );

    [totalCommission, totalRevenue, topPlatform, engagement].forEach(function (c) { grid.appendChild(c); });
  }

  /* ---------- 2. Chart CSS bar — Revenue by Platform ---------- */

  var chartContainer = document.getElementById("platform-revenue-chart");
  if (chartContainer) {
    var maxShare = 0;
    DATA.platforms.forEach(function (p) {
      var s = derived.platformRevenueShare[p.id] || 0;
      if (s > maxShare) maxShare = s;
    });

    var chart = el("table", "charts-css bar show-labels show-4-secondary-axes data-spacing-10");
    chart.setAttribute("aria-label", "Revenue share by platform (percent)");

    DATA.platforms.forEach(function (p) {
      var share = derived.platformRevenueShare[p.id] || 0;
      var size = maxShare > 0 ? share / maxShare : 0;

      var row = el("tr");
      var label = el("th", "", platformName[p.id] || p.id);
      label.setAttribute("scope", "row");
      row.appendChild(label);

      var cell = el("td");
      cell.style.setProperty("--size", String(size));
      cell.style.setProperty("--color", "#3b82f6"); // blue-500 base
      var dataSpan = el("span", "data", pct(share));
      cell.appendChild(dataSpan);
      row.appendChild(cell);

      chart.appendChild(row);
    });

    chartContainer.appendChild(chart);
  }

  /* ---------- 3. Products table ---------- */

  var tbody = document.getElementById("products-tbody");
  if (tbody) {
    DATA.products.forEach(function (prod) {
      var topChannelId = null;
      var topChannelVal = -1;
      Object.keys(prod.platformShare || {}).forEach(function (plId) {
        if (prod.platformShare[plId] > topChannelVal) {
          topChannelVal = prod.platformShare[plId];
          topChannelId = plId;
        }
      });

      var tr = el("tr", "hover:bg-gray-50 dark:hover:bg-slate-700/40 transition-colors duration-150");

      var name = el("td", "px-3 py-3 font-medium text-gray-900 dark:text-slate-100", prod.name);
      var category = el("td", "px-3 py-3 capitalize text-gray-600 dark:text-slate-400", prod.category);
      var price = el("td", "px-3 py-3 text-right text-gray-600 dark:text-slate-400", usd(prod.price));
      var units = el("td", "px-3 py-3 text-right text-gray-600 dark:text-slate-400", Number(prod.unitsSold).toLocaleString("en-US"));
      var revenue = el("td", "px-3 py-3 text-right font-medium text-gray-900 dark:text-slate-100", usd(prod.revenue));
      var commission = el("td", "px-3 py-3 text-right font-medium text-emerald-600 dark:text-emerald-400", usd(prod.commission));
      var conv = el("td", "px-3 py-3 text-right text-gray-600 dark:text-slate-400", pct(prod.conversionRate));
      var channel = el("td", "px-3 py-3 text-gray-600 dark:text-slate-400", platformName[topChannelId] || topChannelId);

      [name, category, price, units, revenue, commission, conv, channel].forEach(function (td) { tr.appendChild(td); });
      tbody.appendChild(tr);
    });
  }

  /* ---------- 4. Footer meta ---------- */

  var footerPeriod = document.getElementById("footer-period");
  if (footerPeriod && DATA.meta && DATA.meta.period) {
    footerPeriod.textContent = DATA.meta.period.start + " \u2013 " + DATA.meta.period.end;
  }

  /* ---------- 5. Scroll-spy for nav (aria-current on active section link) ---------- */

  var navLinks = Array.prototype.slice.call(document.querySelectorAll("nav .nav-link"));
  var sections = ["kpis", "drivers", "details"]
    .map(function (id) { return document.getElementById(id); })
    .filter(Boolean);

  function setActive(id) {
    navLinks.forEach(function (link) {
      var isActive = link.getAttribute("href") === "#" + id;
      if (isActive) {
        link.setAttribute("aria-current", "true");
        link.classList.add("text-sky-600", "dark:text-sky-400");
      } else {
        link.removeAttribute("aria-current");
        link.classList.remove("text-sky-600", "dark:text-sky-400");
      }
    });
  }

  if ("IntersectionObserver" in window && navLinks.length && sections.length) {
    var observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) setActive(entry.target.id);
      });
    }, { rootMargin: "-40% 0px -55% 0px", threshold: 0 });
    sections.forEach(function (s) { observer.observe(s); });
  }
})();